/* Ordered course example; dose fields remain verbatim source text, never evaluated. */
let healthCohort='Adults',healthCourseMode='schedule';
const healthSource={title:'Health DB · Fever',url:'https://docs.google.com/spreadsheets/d/1uvDO_vipNsLcB4S0O7Bj-L8VCSMCd0eX5U9cJS8F-QE/edit',note:'Verified source example: Health DB, Adults SOP / Kids SOP, Fever C2:J18, read 15 Sep 2026. Both groups contain 16 source rows across 3 days.'};
function ensureHealthCourseData(){ensureItemState();state.healthCourses??={};if(typeof HEALTH_FEVER_FIXTURES==='undefined')return;for(const cohort of ['Adults','Kids']){const id='fever-'+cohort.toLowerCase();if(state.healthCourses[id])continue;const raw=HEALTH_FEVER_FIXTURES[cohort]||[];state.healthCourses[id]={id,condition:'Fever',cohort,source:{...healthSource,tab:cohort+' SOP',gid:cohort==='Adults'?582297317:541230517,range:'C2:J18'},version:0,published:null,steps:raw.map((r,index)=>{let itemId='';if(r.medicine){itemId='health-source-'+r.medicine.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(!itemById(itemId)){if(!itemCategory('health-source-medicines'))state.itemCategories.push({id:'health-source-medicines',name:'Source medicine references',module:'Health',parentId:null});if(!itemCategory('health-source-fever'))state.itemCategories.push({id:'health-source-fever',name:'Fever source sheet',module:'Health',parentId:'health-source-medicines'});state.items.push({id:itemId,name:r.medicine,module:'Health',categoryId:'health-source-medicines',subcategoryId:'health-source-fever',description:'Verbatim item name from the Health DB Fever course. Reference-only master record; verify clinical protocol before use.',purpose:'Identify the item in the source course; no prescribing or dose calculation.',unit:'source unspecified',active:true,shares:[],revision:1,referenceOnly:true})}}return {id:id+'-step-'+(index+1),day:r.day,session:r.session||'',type:r.type||'Action',title:r.title||r.medicine||r.treatment||'Source action',itemId,doseRaw:r.dose||'',denominatorRaw:r.denominator||'',routeRaw:r.route||'',treatmentRaw:r.treatment||'',sourceRow:r.row||'',sourceMedicine:r.medicine||''}})};}persist()}
function activeHealthCourse(){ensureHealthCourseData();return state.healthCourses['fever-'+healthCohort.toLowerCase()]}
function visibleHealthCourse(){let c=activeHealthCourse();return canEdit()?c:c?.published}
function healthCourseGroups(c){const groups=[];for(const step of c.steps){let key=step.day+'|'+step.session;let g=groups.find(g=>g.key===key);if(!g){g={key,day:step.day,session:step.session,steps:[]};groups.push(g)}g.steps.push(step)}return groups.sort((a,b)=>Number(a.day)-Number(b.day)||['Morning','Afternoon','Evening',''].indexOf(a.session)-['Morning','Afternoon','Evening',''].indexOf(b.session))}
function renderHealthCourse(){ensureHealthCourseData();let c=visibleHealthCourse(),draft=activeHealthCourse();$('#content').innerHTML=`<div class="heading"><div><h2>Treatment course · ordered care plan</h2><p>Keep each day, session and action together. This is a local authoring example, not a treatment scheduler.</p></div><div class="actions"><button onclick="healthCourseMode=healthCourseMode==='schedule'?'flow':'schedule';renderHealthCourse()">${healthCourseMode==='schedule'?'View course flow':'View schedule'}</button><button onclick="healthStepModal()" ${!canEdit()?'disabled':''}>+ Add step</button><button class="primary" onclick="publishHealthCourse()" ${!canEdit()?'disabled':''}>Review & publish locally</button></div></div><div class="health-course-filters"><label class="field"><span>Condition / course</span><select aria-label="Health course"><option>Fever</option></select></label><label class="field"><span>Animal group</span><select aria-label="Animal group" onchange="healthCohort=this.value;renderHealthCourse()"><option ${healthCohort==='Adults'?'selected':''}>Adults</option><option ${healthCohort==='Kids'?'selected':''}>Kids</option></select></label><span class="badge">${canEdit()?'Local draft':'Published only'}${draft?.version?' · v'+draft.version:''}</span></div><div class="notice">${esc(healthSource.note)} ${healthSource.url?`<a href="${esc(healthSource.url)}#gid=${healthCohort==='Adults'?582297317:541230517}" target="_blank" rel="noreferrer">Open source ↗</a>`:''}<br>Dosage, denominator and route are preserved as raw source text. Missing units remain unspecified. No clinical recommendation or dose calculation is generated.</div>${!c?'<div class="card empty">No published course for this group. CEO / CXO must review and publish a local version first.</div>':`<div class="health-course-summary"><span><b>${c.steps.length}</b> steps</span><span><b>${new Set(c.steps.map(x=>x.day)).size}</b> days</span><span><b>${c.steps.filter(x=>x.itemId).length}</b> item references</span></div><div class="health-${healthCourseMode}">${healthCourseGroups(c).map(g=>`<section class="health-session"><div class="health-session-head"><span class="health-day">Day ${esc(g.day)}</span><h3>${esc(g.session||'Session unspecified')}</h3><span class="muted">${g.steps.length} steps</span></div>${g.steps.map((s,index)=>`<button class="health-step" onclick="healthStepModal('${s.id}')"><span class="health-step-index">${index+1}</span><span><span class="badge ${s.itemId?'purple':'blue'}">${esc(s.type)}</span><b>${esc(s.title)}</b>${s.itemId&&s.title!==(c.items?.[s.itemId]?.name||itemById(s.itemId)?.name||s.sourceMedicine)?`<small>${esc(c.items?.[s.itemId]?.name||itemById(s.itemId)?.name||s.sourceMedicine||'Item unavailable')}</small>`:''}<small>${[s.doseRaw?'Dosage: '+s.doseRaw:'',s.denominatorRaw?'Denominator: '+s.denominatorRaw:'',s.routeRaw?'Route: '+s.routeRaw:''].filter(Boolean).map(esc).join(' · ')||(s.type==='Medication'?'Dosage fields unspecified in source':'')}</small>${s.treatmentRaw&&s.treatmentRaw!==s.title?`<small>${esc(s.treatmentRaw)}</small>`:''}</span><span class="muted">${canEdit()?'Edit ↗':'View ↗'}</span></button>`).join('')}</section>`).join('')}</div>`}`}
function healthStepModal(id){let c=visibleHealthCourse();if(!c)return;let s=id?c.steps.find(s=>s.id===id):{day:1,session:'',type:'Action',title:'',itemId:'',doseRaw:'',denominatorRaw:'',routeRaw:'',treatmentRaw:''};if(!s)return;let itemOptions=canEdit()?availableItems('Health'):Object.values(c.items||{});let dis=!canEdit()?'disabled':'';modal(id?'Course step':'Add course step',`<div class="eyebrow">Fever · ${healthCohort}</div><div class="inputrow"><label class="field"><span>Day</span><input id="hcday" type="number" min="1" step="1" value="${esc(s.day)}" ${dis}></label><label class="field"><span>Session</span><select id="hcsession" ${dis}>${['','Morning','Afternoon','Evening'].map(x=>`<option value="${x}" ${s.session===x?'selected':''}>${x||'Unspecified'}</option>`).join('')}</select></label><label class="field"><span>Record type</span><select id="hctype" ${dis}>${['Action','Medication'].map(x=>`<option ${s.type===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field"><span>Step title</span><input id="hctitle" value="${esc(s.title)}" ${dis}></label><label class="field"><span>Configured item reference</span><select id="hcitem" ${dis}><option value="">No item · action only</option>${itemOptions.map(i=>`<option value="${i.id}" ${s.itemId===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}${s.itemId&&!itemOptions.some(i=>i.id===s.itemId)?`<option selected value="${esc(s.itemId)}">${esc(c.items?.[s.itemId]?.name||itemById(s.itemId)?.name||s.sourceMedicine)} · unavailable</option>`:''}</select></label><div class="inputrow"><label class="field"><span>Dosage · raw source text</span><input id="hcdose" value="${esc(s.doseRaw)}" ${dis}></label><label class="field"><span>Denominator · raw source text</span><input id="hcdenominator" value="${esc(s.denominatorRaw)}" ${dis}></label></div><label class="field"><span>Route · raw source text</span><input id="hcroute" value="${esc(s.routeRaw)}" ${dis}></label><label class="field"><span>Treatment / action details</span><textarea id="hctreatment" ${dis}>${esc(s.treatmentRaw)}</textarea></label><div class="notice">Source row: ${esc(s.sourceRow||'New local step')}. Raw fields are not interpreted. Changing this draft does not change the source sheet.</div><div class="actions"><button class="primary" onclick="saveHealthStep('${id||''}')" ${dis}>Save local draft step</button>${id?`<button class="danger" onclick="removeHealthStep('${id}')" ${dis}>Remove step</button>`:''}</div>`,true)}
function validateCourse(c,items=availableItems('Health')){let errors=[];if(!c||!Array.isArray(c.steps)||!c.steps.length)return ['Add at least one course step.'];let ids=new Set();for(const s of c.steps){if(!s.id)errors.push('Each step needs a stable ID.');if(!['Action','Medication'].includes(s.type))errors.push(s.title+': record type must be Action or Medication.');if(ids.has(s.id))errors.push('Step IDs must be unique.');ids.add(s.id);if(!Number.isInteger(Number(s.day))||Number(s.day)<1)errors.push(s.title+': day must be a positive whole number.');if(!['','Morning','Afternoon','Evening'].includes(s.session))errors.push(s.title+': choose a supported session or leave it unspecified.');if(!s.title?.trim())errors.push('Each step needs a title.');if(s.type==='Medication'&&!s.itemId)errors.push(s.title+': select a configured item reference.');if(s.itemId&&!items.some(i=>i.id===s.itemId))errors.push(s.title+': item reference is unavailable to Health.')}return [...new Set(errors)]}
function saveHealthStep(id){if(!canEdit())return;let c=activeHealthCourse(),old=c.steps.find(s=>s.id===id),s={...old,id:id||'health-step-'+crypto.randomUUID(),day:Number($('#hcday').value),session:$('#hcsession').value,type:$('#hctype').value,title:$('#hctitle').value.trim(),itemId:$('#hcitem').value,doseRaw:$('#hcdose').value,denominatorRaw:$('#hcdenominator').value,routeRaw:$('#hcroute').value,treatmentRaw:$('#hctreatment').value};let errors=validateCourse({...c,steps:[s]});if(errors.length)return toast(errors[0]);if(old)c.steps[c.steps.indexOf(old)]=s;else c.steps.push(s);record('Saved Health course step: '+s.title);closeModal();renderHealthCourse();toast('Course draft saved locally')}
function removeHealthStep(id){if(!canEdit())return;let c=activeHealthCourse();c.steps=c.steps.filter(s=>s.id!==id);record('Removed Health course draft step');closeModal();renderHealthCourse()}
function publishHealthCourse(){if(!canEdit())return;let c=activeHealthCourse(),errors=validateCourse(c);modal(errors.length?'Course needs attention':'Publish course example locally',errors.length?errors.map(e=>`<div class="notice error">${esc(e)}</div>`).join(''):`<p>Fever · ${healthCohort} · ${c.steps.length} ordered steps</p><div class="notice">This creates a local published snapshot for the role preview. It does not schedule tasks, prescribe medicine or send instructions to operators.</div><button class="primary" onclick="confirmHealthPublish()">Publish local snapshot</button>`)}
function confirmHealthPublish(){if(!canEdit())return;let c=activeHealthCourse();let errors=validateCourse(c);if(errors.length){toast(errors[0]);return}if(c.published)(c.versions??=[]).push(structuredClone(c.published));c.version++;c.published=structuredClone({id:c.id,condition:c.condition,cohort:c.cohort,source:c.source,version:c.version,steps:c.steps,items:Object.fromEntries(c.steps.filter(s=>s.itemId).map(s=>[s.itemId,itemById(s.itemId)]))});record('Published Fever '+healthCohort+' course v'+c.version);closeModal();renderHealthCourse()}
const healthBaseRender=render;render=function(){healthBaseRender();if(current==='Health'&&tab!=='Editor'){const tabs=$('.tabs');if(tabs)tabs.insertAdjacentHTML('beforeend',`<button class="${tab==='Treatment courses'?'active':''}" onclick="go('Health','Treatment courses')">Treatment courses</button>`);if(tab==='Treatment courses')renderHealthCourse()}};
const courseBaseItemUsages=itemUsages;
itemUsages=function(id){let usages=courseBaseItemUsages(id);for(const c of Object.values(state.healthCourses||{})){const snapshots=[{course:c,kind:'Draft',active:true},{course:c.published,kind:'Published v'+c.version},...(c.versions||[]).map(v=>({course:v,kind:'Published v'+v.version}))];for(const {course,kind,active} of snapshots){if(!course)continue;for(const step of course.steps||[])if(step.itemId===id)usages.push({title:course.condition+' · '+course.cohort,module:'Health',kind,nodeId:step.id,nodeLabel:step.title,nodeType:step.type,activeDraft:false,courseId:c.id,courseVersion:active?null:course.version,courseActive:!!active,courseStep:structuredClone(step),courseItem:structuredClone(course.items?.[id]||itemById(id))})}}return usages};
const courseBaseOpenUsage=openItemUsage;
openItemUsage=function(id,index){let u=itemUsages(id).filter(u=>canEdit()||u.kind.startsWith('Published'))[index];if(!u?.courseId)return courseBaseOpenUsage(id,index);if(u.courseActive&&canEdit()){closeModal();healthCohort=state.healthCourses[u.courseId].cohort;go('Health','Treatment courses');healthStepModal(u.nodeId);return}const s=u.courseStep;modal('Published course reference',`<h2>${esc(u.title)} · ${esc(u.kind)}</h2><p>Day ${esc(s.day)} · ${esc(s.session||'Unspecified session')} · ${esc(s.type)}</p><div class="notice">${esc(s.title)}<br>Item: ${esc(u.courseItem?.name||s.sourceMedicine)}<br>Dosage (raw): ${esc(s.doseRaw||'Not supplied')} · Denominator (raw): ${esc(s.denominatorRaw||'Not supplied')} · Route (raw): ${esc(s.routeRaw||'Not supplied')}</div><p>Retained course snapshot. No clinical interpretation or action is performed.</p><button onclick="itemModal('${id}')">Back to item</button>`)};
